import { writeFileSync, lstatSync, mkdtempSync, rmSync } from 'node:fs';
import path from 'node:path';
const base = mkdtempSync(path.join(process.argv[2], 'mg2-'));
let same = 0; const n = 5000;
for (let i = 0; i < n; i++) {
  const f = path.join(base, `f${i % 50}`);
  writeFileSync(f, 'aaaa');
  const s1 = lstatSync(f, { bigint: true });   // telelean looks
  writeFileSync(f, 'bbbb');                     // same size, in place, right after
  const s2 = lstatSync(f, { bigint: true });
  if (s1.ctimeNs === s2.ctimeNs && s1.mtimeNs === s2.mtimeNs && s1.size === s2.size && s1.ino === s2.ino) same++;
}
rmSync(base, { recursive: true, force: true });
console.log(JSON.stringify({ n, inPlaceRewriteUndetected: same }));

