  process.stderr.write(`smoke: refused: ${message}\\n`);
  process.exit(2);
}

let argv;
try {
  ({ values: argv } = parseArgs({
    options: {
      'dry-run': { type: 'boolean', default: false },
      live: { type: 'boolean', default: false },
      scenario: { type: 'string', default: 'a,b,c' },
      binary: { type: 'string' },
