/** Every tool result of the run's transcript (edits and reads left out), shortened. */
export function toolResults(runsDir: string, runId: string, max = 1200): string[] {
  const rootKey = readdirSync(runsDir)[0] ?? '';
  return readFileSync(path.join(runsDir, rootKey, runId, 'session', 'transcript.jsonl'), 'utf8')
    .split('\n')
    .filter((l) => l.includes('"tool_result"'))
    .map((l) => (JSON.parse(l) as { event: { text: string } }).event.text.slice(0, max))
    .filter((t) => !t.startsWith('edited ') && !t.startsWith('read '));
}

