// that is not a theorem but carries a proof resting on an UNSELECTED assumption must not pass the gate and must never
// reach the (scratch) user's files. Real engine, real Lean, FakeBackend, scratch git copies of mental_model/.
//
// Not-proved rounds (new-spyro-pg NOT selected): Claude formalises pg-no-dark-past honestly, adds the declaration,
// calls check_lean, then finish(not_proved).
//   mode 'single': no retry. If attempt 1 fails, Claude ends its turn, the nudge turn ends without finish too, and the
//                  round is reverted ("no-finish"); if attempt 1 passes, the helper is in the proposal. We Accept either
//                  way and look at the scratch user's Main.lean: the direct leak test.
//   mode 'retry':  attempt 1, then an edit removing the declaration and attempt 2 (the A2 loop must pass on the retry).
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import type { FakeStep } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/m2verify-r2/repo/packages/runner/src/llm/fake.ts';
