const NO_PG = ['cynder-dark-past', 'pg-no-dark-past'];
const NOT_PROVED = tool('finish', { status: 'not_proved', summary: 'Not proved.', gap: 'x', assumed_without_asking: [] });

async function runOnce(label: string, decl: string, needle: string, mode: 'single' | 'retry'): Promise<Record<string, unknown>> {
  const added = `\n${decl}`;
  const turn1: FakeStep[] = [NORMATIVE_PG, edit(TARGET_LINE, `${TARGET_LINE}${added}`), tool('check_lean'), NOT_PROVED];
  if (mode === 'retry') turn1.push(edit(added, ''), NOT_PROVED);
  turn1.push(result());
  const p = await setup(label, [{ match: 'Run: "These suffice"', steps: turn1 }, { steps: [result()] }]);
  const started = await p.manager.start({ subject: 'Spyro', target: 'cynder-not-good', premises: NO_PG });
  const out: Record<string, unknown> = { mode, decl, started };
  const end = await waitForRun(p.manager, (v) => v.state === 'review' || v.state === 'failed', 600_000, 'review');
  out['review'] = summary(p.manager);
  out['tools'] = toolResults(p.runsDir, end.runId);
  const proposal = p.manager.proposal();
  if (end.state === 'review' && proposal) {
    out['verdict'] = proposal.report.verdict;
    const diff = await p.manager.proposalDiff(end.runId, proposal.proposalId);
    out['proposalHasDecl'] = diff.some((c) => (c.after ?? '').includes(needle));
    out['accept'] = await p.manager.accept(end.runId, proposal.proposalId, proposal.lifecycle.map((l) => l.id), proposal.definitions.map((d) => d.id));
    out['realFileHasDecl'] = readFileSync(path.join(p.root, MAIN), 'utf8').includes(needle);
  }
  await p.manager.dispose();
  return out;
}

