function modelFiles(root: string, rel = '', out = new Map<string, string>()): Map<string, string> {
  for (const name of readdirSync(path.join(root, rel))) {
    if (name.startsWith('.')) continue;
    const child = rel === '' ? name : `${rel}/${name}`;
    if (statSync(path.join(root, child)).isDirectory()) modelFiles(root, child, out);
    else if (child.endsWith('.lean') || ['lakefile.toml', 'lean-toolchain', 'lake-manifest.json'].includes(child)) out.set(child, readFileSync(path.join(root, child), 'utf8'));
  }
  return out;
}

