export type RunMethod =
  | 'start'
  | 'answer'
  | 'cancel'
  | 'resume'
  | 'accept'
  | 'feedback'
  | 'discard'
  | 'adoptGhost'
  | 'rejectGhost'
  | 'dismiss'
  | 'proposalDiff'
  | 'recover'
  | 'dispose';

/**
 * A recording RunManager. Like the real one (WP3), `start` obtains the backend from `options.services.backend` when
 * that is a factory (a rejection refuses the start `not-yet` with its message); everything else only records.
 */
export class FakeRunManager implements RunManager {
  calls: Array<{ method: RunMethod; args: unknown[] }> = [];
  run: RunView | null = null;
  currentProposal: ProposalView | null = null;
  /** The outcome every action method resolves with (or computes from the call). */
  outcome: ActionOutcome | ((method: RunMethod, args: unknown[]) => ActionOutcome | Promise<ActionOutcome>) = (method) => ({
    ok: true,
    label: `did ${method}`,
    undoable: method === 'accept',
  });
  /** What `proposalDiff` resolves with (an Error: it rejects). */
  diffFiles: FileChange[] | Error = [
    { path: 'Model/Spyro/Main.lean', before: 'abbrev a : Prop := True\n', after: 'abbrev a : Prop := True\ntheorem a.holds : a := trivial\n' },
    { path: 'Model/Spyro/Lemmas.lean', before: null, after: 'namespace Spyro\nend Spyro\n' },
  ];
  /** The backend `start` obtained. */
  backend?: LlmBackend;
  /** `recover()` waits for it (tests can hold the recovery back). */
  recovery: Promise<void> = Promise.resolve();
  /** What `dispose` returns (a promise simulates an asynchronous persist + close). */
  disposeResult: unknown = undefined;
  onDispose?: () => void;
  private readonly listeners = new Set<(change: RunChange) => void>();

  constructor(readonly options?: RunManagerOptions) {}

  current(): RunView | null {
    return this.run;
  }
  proposal(): ProposalView | null {
    return this.currentProposal;
  }
  onDidChange(listener: (change: RunChange) => void): Disposable {
    this.listeners.add(listener);
    return { dispose: () => void this.listeners.delete(listener) };
  }
  fire(change: RunChange = { run: true, proposal: true }): void {
    for (const listener of [...this.listeners]) listener(change);
  }
  get listenerCount(): number {
    return this.listeners.size;
  }
  /** Calls of one method, in order. */
  callsOf(method: RunMethod): unknown[][] {
    return this.calls.filter((c) => c.method === method).map((c) => c.args);
  }

  private async resolve(method: RunMethod, args: unknown[]): Promise<ActionOutcome> {
    this.calls.push({ method, args });
    return typeof this.outcome === 'function' ? this.outcome(method, args) : this.outcome;
  }

  async start(request: RunStartRequest): Promise<ActionOutcome> {
    const backend = this.options?.services.backend;
    if (typeof backend === 'function') {
      try {
        this.backend = await backend();
      } catch (error) {
        this.calls.push({ method: 'start', args: [request] });
        return { ok: false, code: 'not-yet', error: error instanceof Error ? error.message : String(error) };
      }
    } else if (backend) {
      this.backend = backend;
    }
    return this.resolve('start', [request]);
  }
  answer(runId: string, setId: string, answers: readonly QuestionAnswer[]): Promise<ActionOutcome> {
    return this.resolve('answer', [runId, setId, answers]);
  }
  cancel(runId: string): Promise<ActionOutcome> {
    return this.resolve('cancel', [runId]);
  }
  resume(runId: string): Promise<ActionOutcome> {
    return this.resolve('resume', [runId]);
  }
  accept(runId: string, proposalId: string, lifecycle: readonly string[], definitions: readonly string[]): Promise<ActionOutcome> {
    return this.resolve('accept', [runId, proposalId, lifecycle, definitions]);
  }
  feedback(runId: string, text: string): Promise<ActionOutcome> {
    return this.resolve('feedback', [runId, text]);
  }
  discard(runId: string): Promise<ActionOutcome> {
    return this.resolve('discard', [runId]);
  }
  adoptGhost(runId: string, ghostId: string, rationale?: string): Promise<ActionOutcome> {
    return this.resolve('adoptGhost', rationale === undefined ? [runId, ghostId] : [runId, ghostId, rationale]);
  }
  rejectGhost(runId: string, ghostId: string): Promise<ActionOutcome> {
    return this.resolve('rejectGhost', [runId, ghostId]);
  }
  dismiss(runId: string): Promise<ActionOutcome> {
    return this.resolve('dismiss', [runId]);
  }
  async proposalDiff(runId: string, proposalId: string): Promise<FileChange[]> {
    this.calls.push({ method: 'proposalDiff', args: [runId, proposalId] });
    if (this.diffFiles instanceof Error) throw this.diffFiles;
    return this.diffFiles;
  }
  async recover(): Promise<void> {
    this.calls.push({ method: 'recover', args: [] });
    await this.recovery;
  }
  dispose(): void {
    this.calls.push({ method: 'dispose', args: [] });
    this.onDispose?.();
    return this.disposeResult as void;
  }
}

// Injected into every CommonJS bundle of the extension (esbuild `inject`, scripts/esbuild-options.mjs), which defines
// `import.meta.url` as this value: the bundle's own file URL. The runner's llm/ modules and its path-guard module read
// `import.meta.url` (the guard's default path, the guard module's "am I the entry point?" check); in CommonJS esbuild
// would otherwise leave it undefined, and `new URL(relative, undefined)` throws (docs/m2-plan.md section 8.4, risk R2).
// The extension never relies on that default: it always passes the guard script's path (dist/bin/) explicitly.
import { pathToFileURL } from 'node:url';

export const teleleanImportMetaUrl = pathToFileURL(__filename).href;

// esbuild options shared by scripts/build.mjs and the bundle test (test/unit/bundle.test.ts).
// `@telelean/core` and `@telelean/runner/*` resolve through the tsconfig `paths` entries to the package sources.
import { fileURLToPath } from 'node:url';

/** Injected module that provides `import.meta.url` in the CommonJS bundles (see import-meta-url.mjs). */
export const IMPORT_META_URL_INJECT = fileURLToPath(new URL('./import-meta-url.mjs', import.meta.url));

/** @param {string} root absolute path of packages/extension */
export function commonOptions(root) {
  /** @type {import('esbuild').BuildOptions} */
  const options = {
    absWorkingDir: root,
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node22',
    sourcemap: true,
    tsconfig: 'tsconfig.json',
    logLevel: 'info',
    // M2: the runner's llm/ modules and its path guard are bundled; their `import.meta.url` becomes the bundle's own
    // file URL (an injected constant), never undefined (docs/m2-plan.md section 8.4).
    define: { 'import.meta.url': 'teleleanImportMetaUrl' },
    inject: [IMPORT_META_URL_INJECT],
  };
  return options;
}

/** src/extension.ts -> dist/extension.js (CommonJS, `vscode` external). */
export function extensionOptions(root) {
  /** @type {import('esbuild').BuildOptions} */
  const options = { ...commonOptions(root), entryPoints: ['src/extension.ts'], outfile: 'dist/extension.js', external: ['vscode'] };
  return options;
}

/** test/suite/*.test.ts -> out/test/suite/*.test.js (loaded by @vscode/test-cli's mocha runner). */
export function suiteOptions(root) {
  /** @type {import('esbuild').BuildOptions} */
  // playwright-core (installed with @playwright/test) is loaded from the repository's node_modules at run time.
  const options = { ...commonOptions(root), entryPoints: ['test/suite/*.test.ts'], outdir: 'out/test/suite', external: ['vscode', 'mocha', 'playwright-core'] };
  return options;
}

// Build steps besides esbuild itself, shared by scripts/build.mjs and the unit tests (test/unit/bundle.test.ts):
//   copyGuardScript    the runner's PreToolUse path guard -> dist/bin/telelean-path-guard.mjs (the Claude CLI runs it
//                      as a hook; the extension passes this path explicitly, docs/m2-plan.md section 8.4)
//   checkBundleLoads   requires the bundle in a separate Node process with a stub `vscode` module: it must load and
//                      export activate/deactivate (a module-load crash, e.g. from `import.meta.url`, fails the build)
import { spawnSync } from 'node:child_process';
import { copyFile, mkdir, readFile } from 'node:fs/promises';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

/** packages/runner/bin/telelean-path-guard.mjs */
export const GUARD_SOURCE = fileURLToPath(new URL('../../runner/bin/telelean-path-guard.mjs', import.meta.url));
export const GUARD_NAME = 'telelean-path-guard.mjs';
const CHECK_SCRIPT = fileURLToPath(new URL('./check-bundle.cjs', import.meta.url));

/**
 * Copies the guard script to `<distDir>/bin/` and checks the copy is byte-identical; returns its path.
 * @param {string} distDir absolute path of the dist folder (packages/extension/dist in the build)
 */
export async function copyGuardScript(distDir) {
  const target = path.join(distDir, 'bin', GUARD_NAME);
  await mkdir(path.dirname(target), { recursive: true });
  await copyFile(GUARD_SOURCE, target);
  const [source, copy] = await Promise.all([readFile(GUARD_SOURCE), readFile(target)]);
  if (!source.equals(copy)) throw new Error(`the copied path guard ${target} differs from ${GUARD_SOURCE}`);
  return target;
}

/**
 * Loads the bundle in a fresh Node process with a stub `vscode` module; throws with its output when it fails.
 * @param {string} bundle absolute path of the bundle
 */
export function checkBundleLoads(bundle) {
  const result = spawnSync(process.execPath, [CHECK_SCRIPT, bundle], { encoding: 'utf8', timeout: 60_000, env: { ...process.env, TELELEAN_NO_REAL_CLAUDE: '1' } });
  if (result.status !== 0) {
    throw new Error(`the bundle ${bundle} does not load in Node: ${(result.stderr || result.stdout || String(result.error ?? '')).trim()}`);
  }
  return result.stdout.trim();
}

// Usage: node scripts/check-bundle.cjs <bundle.js>  (scripts/build-steps.mjs checkBundleLoads)
// Requires the extension bundle with a minimal stub `vscode` module (nothing is activated) and checks its exports.
// Module-load errors (a missing dependency, `import.meta.url` in CommonJS, …) make it exit non-zero.
'use strict';
const Module = require('node:module');
const path = require('node:path');

const bundle = path.resolve(process.argv[2] || '');
const stubId = path.join(path.dirname(bundle), '__vscode_stub__.js');
const stub = { version: '0.0.0-build-check', ExtensionMode: { Production: 1, Development: 2, Test: 3 } };
const originalResolve = Module._resolveFilename;
Module._resolveFilename = function (request, ...rest) {
  return request === 'vscode' ? stubId : originalResolve.call(this, request, ...rest);
};
require.cache[stubId] = { id: stubId, filename: stubId, loaded: true, exports: stub };

const extension = require(bundle);
const missing = ['activate', 'deactivate'].filter((name) => typeof extension[name] !== 'function');
if (missing.length > 0) {
  console.error(`the bundle does not export ${missing.join(' and ')}`);
  process.exit(1);
}
