  const temp = path.join(tempDir, `${path.basename(absolute)}.${process.pid}-${++tempCounter}.tmp`);
  try {
    await writeFile(temp, text, 'utf8');
    await rename(temp, absolute);
  } catch (error) {
    await rm(temp, { force: true }).catch(() => undefined);
    throw error;
  }
}"""),
