function blockTexts(parsed) { return parsed.blocks.map(b => parsed.text.slice(b.span.start, b.span.end)); }
function declTexts(parsed) { return parsed.decls.map(d => parsed.text.slice(d.span.start, d.span.end)); }
function commentKinds(text) { return lexer.lexLean(text).comments.map(c => c.kind + (c.unterminated ? '!' : '')); }

// set one field and verify: field reads back, other blocks/decls identical, comment structure identical
function roundTrip(name, text, blockIndex, key, value, expectRead) {
  const p = parseLeanFile('Model/S/Main.lean', text);
  const b = p.blocks[blockIndex];
  if (!b) { check(name, false, 'no block ' + blockIndex + ' diags=' + show(p.diagnostics)); return; }
  let after;
  try { after = applyTextEdits(text, setBlockField(p, b, key, value)); } catch (e) { check(name, false, 'threw ' + e.message); return; }
  const q = parseLeanFile('Model/S/Main.lean', after);
  const others = (arr) => arr.filter((_, i) => i !== blockIndex);
  const okOthers = show(others(blockTexts(p))) === show(others(blockTexts(q)));
  const okDecls = show(declTexts(p)) === show(declTexts(q));
  const okComments = show(commentKinds(text)) === show(commentKinds(after));
  const nb = q.blocks[blockIndex];
  const fieldKey = { natural_name: 'naturalName' }[key] ?? key;
  const got = nb?.fields?.[fieldKey];
  const want = expectRead === undefined ? value : expectRead;
  const okField = show(got) === show(want);
  // unknown/extension keys preserved
  const okExt = show(b.extensions) === show(nb?.extensions);
  // no new diagnostics of error severity in this block
  const errs = q.diagnostics.filter(d => d.severity === 'error' && d.nodeId === nb?.id && d.code !== 'TL005');
  const okEol = !after.replace(/\r\n/g, '').includes('\r') || text.includes('\r');
  const mixedEol = text.includes('\r\n') && /[^\r]\n/.test(after);
  check(name, okOthers && okDecls && okComments && okField && okExt && errs.length === 0 && !mixedEol,
    show({ okOthers, okDecls, okComments, okField, got, want, okExt, errs: errs.map(e => e.code + ':' + e.message), mixedEol, after }));
  return after;
}

