    if (c.after === null) continue;
    if (!c.path.endsWith('.lean')) continue;
    const lf = (c.after.match(/(?<!\r)\n/g) ?? []).length;
    const crlf = (c.after.match(/\r\n/g) ?? []).length;
    if (c.before !== null && lf > 0) problems.push(`${c.path}: ${lf} bare LF among ${crlf} CRLF`);
    const lx = lexer.lexLean(c.after);
    if (lx.comments.some(x => x.unterminated)) problems.push(`${c.path}: unterminated comment`);
    const p = core.parseLeanFile(c.path, c.after);
    const errs = p.diagnostics.filter(d => d.severity === 'error');
    if (errs.length) problems.push(`${c.path}: markup errors ${J(errs.map(e => e.code + ' ' + e.message))}`);
