      const untouchedAfter = p.blocks.filter(b => !plan.nodes.includes(b.id)).map(b => c.after.slice(b.span.start, b.span.end));
      if (J(untouchedBefore) !== J(untouchedAfter)) problems.push(`${c.path}: an untouched block changed`);
    }
  }
  console.log(problems.length ? 'PROBLEM' : 'ok', a.kind, a.id ?? a.name ?? '', a.field ?? a.to ?? '', J(problems));
