// Seeded fuzz: setBlockFields with delimiter-heavy values on varied block layouts; invariants: value reads back,
// other blocks/decls byte-identical, comment structure unchanged, no unterminated comment, EOL style kept.
import { markup, lexer, core } from '../harness/bundle.mjs';
const { parseLeanFile, setBlockFields, applyTextEdits } = markup;
let seed = 12345;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const ALPHA = ['-', '/', '-', '/', '"', '\\', "'", ' ', '\t', ':', ',', '[', ']', '{', '}', '«', '»', '𝔸', ' ', '#', '@', 'a', 'b', 'x', '*', '!', '\u0085', '`'];
const randomValue = (allowNewline) => { let s = ''; const n = 1 + Math.floor(rnd() * 12); for (let i = 0; i < n; i++) s += allowNewline && rnd() < 0.05 ? '\n' : pick(ALPHA); return s; };
const layouts = [
  (f, eol) => ['/-', '@@ telelean v1', ...f, '-/'].join(eol),
  (f, eol) => ['/- @@ telelean v1', ...f.slice(0, -1), `${f[f.length - 1]} -/`].join(eol),
  (f, eol) => ['/-', '@@ telelean v1', ...f.slice(0, -1), `${f[f.length - 1]}-/`].join(eol),
  (f, eol) => ['  /-', '  @@ telelean v1', ...f.map((l) => '  ' + l), '  -/'].join(eol),
  (f, eol) => ['/-', '@@ telelean v1', ...f, '---', 'body /- nested -/ text', '-/'].join(eol),
];
let failures = 0, runs = 0;
for (let iter = 0; iter < 3000; iter++) {
  const eol = rnd() < 0.3 ? '\r\n' : '\n';
  const fields = ['id: n1', 'type: ASSUMPTION', 'natural_name: Start', 'x.ext: keep -this', 'odd: thing'];
  if (rnd() < 0.5) fields.splice(3, 0, 'rationale: old');
  const layout = pick(layouts);
  const block = layout(fields, eol);
  const text = ['namespace S', '', '/-', '@@ telelean v1', 'id: other', 'type: GOAL', 'natural_name: Other', '-/', '', block, 'abbrev s1 : Prop := True', 'axiom s1.holds : s1', '', 'end S', ''].join(eol);
  const p = parseLeanFile('M.lean', text);
  const b = p.blocks.find((x) => x.id === 'n1');
  if (!b) { failures++; console.log('setup: block not found', JSON.stringify(block)); continue; }
  const changes = [];
  const nKeys = 1 + Math.floor(rnd() * 3);
  for (let k = 0; k < nKeys; k++) {
    const key = pick(['natural_name', 'rationale', 'stance', 'source', 'premises', 'lean']);
    let value;
    if (key === 'stance') value = pick(['believe', 'rule', 'supposing', null]);
    else if (key === 'source') value = pick(['observed', 'reported', null]);
    else if (key === 'premises') value = pick([['a-1', 'b_2'], [], null, ['c.3']]);
    else if (key === 'lean') value = pick([['S.s1'], null]);
    else value = rnd() < 0.1 ? null : randomValue(key === 'rationale');
    changes.push({ key, value });
  }
  let after;
  runs++;
  try { after = applyTextEdits(text, setBlockFields(p, b, changes)); } catch (e) { failures++; console.log('threw', e.message); continue; }
  const q = parseLeanFile('M.lean', after);
  const nb = q.blocks.find((x) => x.id === 'n1');
  const want = new Map(changes.map((c) => [c.key, c.value]));
  const problems = [];
  if (!nb) problems.push('block lost');
  else {
    const map = { natural_name: 'naturalName' };
    for (const [key, value] of want) {
      const got = nb.fields[map[key] ?? key];
      const expect = value === null || (Array.isArray(value) && value.length === 0) ? undefined : value;
      if (JSON.stringify(got) !== JSON.stringify(expect)) problems.push(`${key}: got ${JSON.stringify(got)} want ${JSON.stringify(expect)}`);
    }
    if (JSON.stringify(nb.extensions) !== JSON.stringify(b.extensions)) problems.push('extensions changed');
    if (b.body !== nb.body) problems.push('body changed');
  }
  const other = (pp, t) => pp.blocks.filter((x) => x.id !== 'n1').map((x) => t.slice(x.span.start, x.span.end));
  if (JSON.stringify(other(p, text)) !== JSON.stringify(other(q, after))) problems.push('other block changed');
  const decls = (pp, t) => pp.decls.map((d) => t.slice(d.span.start, d.span.end));
  if (JSON.stringify(decls(p, text)) !== JSON.stringify(decls(q, after))) problems.push('decls changed');
  const lx = lexer.lexLean(after);
  if (lx.comments.length !== lexer.lexLean(text).comments.length || lx.comments.some((c) => c.unterminated)) problems.push('comment structure changed');
  if (eol === '\r\n' && /(?<!\r)\n/.test(after)) problems.push('bare LF in CRLF file');
  if (q.blocks.find((x) => x.id === 'n1')?.binding.mode !== p.blocks.find((x) => x.id === 'n1')?.binding.mode && !want.has('lean')) problems.push('binding changed');
  if (problems.length) { failures++; if (failures <= 8) console.log('FAIL', JSON.stringify(problems), '\nchanges', JSON.stringify(changes), '\nblock before:\n' + block + '\nafter:\n' + after.slice(after.indexOf('id: n1') - 20, after.indexOf('abbrev s1'))); }
}
console.log(`${runs} runs, ${failures} failures`);

