// What registry.onFileEvent decides for the file events of two quick telelean writes to the same file
// (e.g. "Revert" then "Undo"), when the first write's event is handled after the second write was recorded
// (onWillWrite records before VS Code writes) but before the second write reached the disk.
import { SelfWrites } from '$R/packages/extension/src/logic/changeBatcher.ts';
const w = new SelfWrites();
const file = '/m/Model/Spyro/Inbox.lean';
w.record([{ absPath: file, text: 'T1 (after the add)' }]);      // write 1 recorded, then written
