  setSetting(path.join(SCRATCH, 'run1'), 'telelean.memory.minAvailableGiB', undefined);
  await palette(page, 'View: Close All Editors');
  await sleep(1500);
  await palette(page, 'Developer: Reload Window');
  await sleep(1000);
}

import { boardFrame, palette, shot, sleep, waitFor } from './lib.mjs';
export default async function ({ page }) {
  await sleep(3000);
  await palette(page, 'telelean: Open Board');
  await sleep(800);
  await page.locator('.quick-input-widget .monaco-list-row').filter({ hasText: 'mental_model' }).first().click();
  const f = await boardFrame(page, 30000, '.tl-app', 'mental_model');
  const badge = f.getByTestId('lean-badge');
  await waitFor(async () => (await badge.getAttribute('data-state')) === 'fresh', 120000, 'fresh', 500);
  const card = f.locator('[data-node-id="new-spyro-pg"]');
  await card.locator('.tl-card__chevron').click();
  await sleep(300);
  const btn = card.locator('.tl-details__actions').getByRole('button', { name: 'Make Derivation' });
  console.log('Make Derivation title:', await btn.getAttribute('title'));
  await btn.click();
  await sleep(500);
  console.log('dialog?', await f.locator('dialog[open]').count());
  await waitFor(async () => (await badge.getAttribute('data-state')) === 'fresh' && (await f.locator('.tl-col[data-kind="DERIVATION"] [data-node-id="new-spyro-pg"]').count()) > 0, 120000, 'moved+fresh', 500);
  await sleep(800);
  console.log('new-spyro-pg chips:', await f.locator('[data-node-id="new-spyro-pg"] [data-chip]').allInnerTexts());
  console.log('goal chips:', await f.locator('[data-node-id="cynder-not-good"] [data-chip]').allInnerTexts());
  await shot(page, '106-promotion-pending-dark');
  await f.locator('button[aria-label="Undo"].tl-icon-button--toolbar').click();
  await sleep(1500);
  console.log('after undo in ASSUMPTION col:', await f.locator('.tl-col[data-kind="ASSUMPTION"] [data-node-id="new-spyro-pg"]').count());
}

import { boardFrame, shot, sleep, waitFor } from './lib.mjs';
export default async function ({ page }) {
  const f = await boardFrame(page, 30000, '.tl-app', 'mental_model');
  for (const chev of await f.locator('.tl-card__chevron[aria-expanded="true"]').all()) await chev.click();
  for (const b of await f.locator('.tl-toast [aria-label="Dismiss"]').all()) await b.click().catch(() => {});
  await f.locator('[data-node-id="toast-test-one"]').click();
  await f.locator('[data-node-id="cynder-dark-past"]').click({ modifiers: ['Control'] });
  await f.locator('[data-node-id="cynder-not-good"]').click({ modifiers: ['Control'] });
  await sleep(300);
  await f.getByRole('button', { name: /These suffice/ }).click();
  const badge = f.getByTestId('lean-badge');
  await sleep(1000);
  await waitFor(async () => (await badge.getAttribute('data-state')) === 'fresh', 120000, 'fresh', 500);
  await f.getByRole('button', { name: 'Clear' }).click();
  await sleep(800);
  console.log('edges:', await f.locator('path[data-edge-id]').evaluateAll((els) => els.map((e) => e.getAttribute('data-edge-id') + ' ' + e.getAttribute('class'))));
  await shot(page, '107-mismatch-dark');
  await f.getByTestId('problems-button').click();
  await sleep(300);
  console.log('PROBLEMS:', (await f.getByTestId('problems-menu').innerText()).replace(/\n+/g, ' | '));
  await page.keyboard.press('Escape');
  // hover the goal for focus colouring
  await f.locator('[data-node-id="cynder-not-good"]').hover();
  await sleep(400);
  await shot(page, '108-mismatch-hover-dark');
  await page.mouse.move(5, 5);
  await f.locator('button[aria-label="Undo"].tl-icon-button--toolbar').click();
  await sleep(1500);
}

import { boardFrame, palette, shot, sleep } from './lib.mjs';
export default async function ({ page }) {
  await palette(page, 'telelean: Open Board');
  await sleep(800);
  await page.locator('.quick-input-widget .monaco-list-row').filter({ hasText: 'big_model' }).first().click();
  await sleep(5000);
  await shot(page, '109-broken-layout-dark');
  console.log('notifications:', JSON.stringify(await page.locator('.notification-toast').allInnerTexts()));
  try {
    const f = await boardFrame(page, 10000);
    console.log('board text:', (await f.locator('.tl-app').innerText()).replace(/\n+/g, ' | ').slice(0, 600));
    console.log('toasts:', await f.getByTestId('toast').allInnerTexts());
  } catch (e) { console.log('no board frame:', e.message); }
}

