// Reload check for the restored-board blocker: opens two boards in an isolated VS Code 1.140 test instance (over CDP,
// loopback only), reloads the window twice, and checks that both restored boards render their cards.
import { chromium } from '/home/zhengyew/telelean/node_modules/playwright-core/index.mjs';

const port = process.argv[2];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log(new Date().toISOString().slice(11, 23), ...a);

async function connect(timeoutMs = 90000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      const browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
      for (;;) {
        const page = browser.contexts().flatMap((c) => c.pages()).find((p) => p.url().includes('workbench.html'));
        if (page) return { browser, page };
        if (Date.now() > deadline) throw new Error('no workbench page');
        await sleep(250);
      }
    } catch (e) {
      if (Date.now() > deadline) throw e;
      await sleep(500);
    }
  }
}

async function palette(page, command, pick) {
  await page.keyboard.press('F1');
  const input = page.locator('.quick-input-widget input');
  await input.waitFor({ timeout: 15000 });
  await input.fill(`>${command}`);
  await sleep(500);
  await page.keyboard.press('Enter');
  if (pick) {
    await sleep(800);
    await input.fill(pick);
    await sleep(400);
    await page.keyboard.press('Enter');
  }
}

/** Board frames that show cards: [{ root, cards }]. */
async function boards(page) {
  const out = [];
  for (const frame of page.frames()) {
    if (frame.isDetached() || !frame.url().startsWith('vscode-webview://')) continue;
    try {
      const info = await frame.evaluate(() => {
        const app = document.querySelector('.tl-app');
        if (!app) return null;
        return { root: document.querySelector('.tl-toolbar__root')?.textContent ?? '?', cards: document.querySelectorAll('[data-node-id]').length, waiting: !!document.querySelector('.tl-board__waiting') };
      });
      if (info) out.push(info);
    } catch {}
  }
  return out;
}

async function waitBoard(page, root, label, timeoutMs = 60000) {
  const t0 = Date.now();
  for (;;) {
    const found = (await boards(page)).find((b) => b.root === root && b.cards >= 4);
    if (found) {
      log(`${label}: board "${root}" renders ${found.cards} cards after ${Date.now() - t0} ms`);
      return true;
    }
    if (Date.now() - t0 > timeoutMs) {
      const iframes = await page.evaluate(() => document.querySelectorAll('iframe').length).catch(() => -1);
      log(`${label}: board "${root}" NOT rendered after ${timeoutMs} ms; iframes in the workbench: ${iframes}; boards seen: ${JSON.stringify(await boards(page))}`);
      return false;
    }
    await sleep(250);
  }
}

async function tabs(page) {
  return page.locator('.tabs-container .tab').allInnerTexts().catch(() => []);
}

async function clickTab(page, text) {
  await page.locator('.tabs-container .tab', { hasText: text }).first().click();
}

