// TEMPORARY exploration: the person adds a card while Claude works (deleted before the end).
import { mkdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { describe, it } from 'vitest';

import { createLeanCheckEngine } from '../../src/gate/index.js';
import { FakeBackend } from '../../src/llm/fake.js';
import { playFakeScript, validateFakeScriptFile, type FakeScriptFile } from '../../src/llm/fakeScripts.js';
import { createProposalService, createRunSidecarStore } from '../../src/proposal/index.js';
import { createRunManager, DEFAULT_RUN_SETTINGS } from '../../src/run/index.js';
import { createModelWorkspace, fsEditApplier, fsTextSource, inspectFolder, planInitialize } from '../../src/workspace/index.js';
import { makeTempDir, REPO_ROOT } from './helpers/env.js';
import { waitForRun } from './helpers/harness.js';

describe('drift', () => {
  for (const when of ['review', 'edit-rationale', 'edit-target-rationale']) {
    it(when, async () => {
      const file = validateFakeScriptFile(JSON.parse(readFileSync(path.join(REPO_ROOT, 'test-fixtures', 'fresh', 'socrates.json'), 'utf8'))) as FakeScriptFile & { cards: Array<{ type: 'ASSUMPTION' | 'GOAL'; naturalName: string }> };
      const dir = makeTempDir('drift');
      const root = path.join(dir, 'demo');
      mkdirSync(root);
      await fsEditApplier(root).apply(planInitialize({ subject: 'Demo', inspection: await inspectFolder(root) }), 'Initialize model');
      const ws = createModelWorkspace({ root, text: fsTextSource(root), applier: fsEditApplier(root), semantic: { debounceMs: 60_000 }, now: () => new Date('2026-11-10T12:00:00Z') });
      await ws.load();
      await ws.initGit();
      for (const c of file.cards) await ws.perform({ kind: 'add-node', subject: 'Demo', type: c.type, naturalName: c.naturalName });
      await ws.refreshNow();
      const play = playFakeScript(file);
      const manager = createRunManager({ root, runsDir: path.join(dir, 'runs'), workspace: ws, services: { backend: new FakeBackend(play.script), engine: createLeanCheckEngine(), proposals: createProposalService(), sidecars: createRunSidecarStore() }, settings: DEFAULT_RUN_SETTINGS });
      await manager.start({ subject: 'Demo', target: 'socrates-is-mortal', premises: ['all-humans-are-mortal', 'socrates-is-a-human'] });
      const end = await waitForRun(manager, (v) => v.state === 'review' || v.state === 'failed', 300_000);
      let out;
      if (when === 'review') out = await ws.perform({ kind: 'add-node', subject: 'Demo', type: 'ASSUMPTION', naturalName: 'Plato is a human' });
      else if (when === 'edit-rationale') out = await ws.perform({ kind: 'edit-node', id: 'socrates-is-a-human', field: 'rationale', value: 'I read it' });
      else out = await ws.perform({ kind: 'edit-node', id: 'socrates-is-mortal', field: 'rationale', value: 'the classic' });
      console.log(`### ${when}: user action ${JSON.stringify(out)}`);
      const p = manager.proposal();
      const accepted = await manager.accept(end.runId, p?.proposalId ?? '', p?.lifecycle.map((l) => l.id) ?? [], p?.definitions.map((d) => d.id) ?? []);
      console.log(`### ${when}: accept ${JSON.stringify(accepted)} state=${manager.current()?.state} notices=${JSON.stringify(manager.current()?.notices.map((n) => n.text))}`);
      console.log(readFileSync(path.join(root, 'Model/Demo/Inbox.lean'), 'utf8'));
      await manager.dispose();
      ws.dispose();
    });
  }
});

