}
{ // reverse: telelean write T1, then the user's save U recorded before T1's event is handled
  const s = fresh(); s.selfWrites.record([{ absPath: P, text: 'T1' }]); s.userSaves.record([{ absPath: P, text: 'U' }]);
  out.T1_then_U = [await ev(s, 'T1'), await ev(s, 'U')];
}
{ // action then Undo (two telelean writes), events late
  const s = fresh(); s.selfWrites.record([{ absPath: P, text: 'T1' }]); s.selfWrites.record([{ absPath: P, text: 'T0' }]);
  out.action_undo = [await ev(s, 'T1'), await ev(s, 'T0'), await ev(s, 'T0')];
