    sw.record([{ absPath: P, text: 'B' }]);
    sw.record([{ absPath: P, text: 'A' }]);
    out.aba = [sw.isEcho(P, 'A', 'disk'), sw.isEcho(P, 'B', 'disk'), sw.isEcho(P, 'A', 'disk')];
  }
