// Read-only observer: waits for "DevTools listening on ws://127.0.0.1:<port>" in a smoke log, then polls the
// workbench page over raw CDP (Runtime.evaluate) every 300 ms and logs VS Code notification toasts (text + rect).
// usage: node notif-observer.mjs <smoke-log> <out-log> <max-seconds>
import { readFileSync, appendFileSync } from 'node:fs';
const [logPath, outPath, maxS] = process.argv.slice(2);
const end = Date.now() + Number(maxS) * 1000;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const out = (s) => appendFileSync(outPath, `${new Date().toISOString().slice(11, 23)} ${s}\n`);
const seenPorts = new Set();
async function watch(port) {
  let ws;
  for (let i = 0; i < 100 && !ws; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
      const page = list.find((t) => t.type === 'page' && t.url.includes('workbench.html'));
      if (page) ws = new WebSocket(page.webSocketDebuggerUrl);
    } catch {}
    if (!ws) await sleep(300);
  }
  if (!ws) { out(`port ${port}: no workbench page`); return; }
  await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
  out(`port ${port}: attached`);
  let id = 0; const pending = new Map();
  ws.onmessage = (ev) => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  ws.onclose = () => out(`port ${port}: closed`);
  const evalJs = (expression) => new Promise((resolve) => { const i = ++id; pending.set(i, resolve); ws.send(JSON.stringify({ id: i, method: 'Runtime.evaluate', params: { expression, returnByValue: true } })); setTimeout(() => { if (pending.has(i)) { pending.delete(i); resolve(null); } }, 2000); });
  let last = '';
  while (Date.now() < end && ws.readyState === 1) {
    const r = await evalJs(`JSON.stringify([...document.querySelectorAll('.notifications-toasts .notification-toast')].map(e => { const b = e.getBoundingClientRect(); return { text: (e.innerText||'').replace(/\\s+/g,' ').trim().slice(0,300), rect: [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)] }; }))`);
    const v = r?.result?.result?.value ?? 'ERR';
    if (v !== last) { out(`port ${port}: toasts ${v}`); last = v; }
    await sleep(300);
  }
  try { ws.close(); } catch {}
}
while (Date.now() < end) {
  let text = '';
  try { text = readFileSync(logPath, 'utf8'); } catch {}
  for (const m of text.matchAll(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)\//g)) {
    if (!seenPorts.has(m[1])) { seenPorts.add(m[1]); out(`found port ${m[1]}`); void watch(m[1]); }
  }
  if (/\[smoke\] vscode-test exit code/.test(text)) { await sleep(1500); break; }
  await sleep(500);
}
out('observer done');
process.exit(0);

